/* Hoja portable: sin peticiones de red, librerías ni módulos ES. */
(()=>{'use strict';
const D=window.VAL_DATA,C=window.ValCore,KEY='hoja-dnd:'+C.ID+':v1';
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const signed=x=>x===null?'Pendiente':(x>=0?'+':'')+x;
const number=x=>x===null?'—':new Intl.NumberFormat('es-MX',{maximumFractionDigits:2}).format(x);
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const localDate=()=>{const n=new Date();return n.getFullYear()+'-'+String(n.getMonth()+1).padStart(2,'0')+'-'+String(n.getDate()).padStart(2,'0');};
let state=C.defaultState(D),storageOkay=true,readProblem=false,corruptRaw='',toastTimer,activeTab='ficha',busy=false,lastDamageDC=null;
try{const raw=localStorage.getItem(KEY);if(raw)state=C.validateState(JSON.parse(raw));localStorage.setItem(KEY+':probe','1');localStorage.removeItem(KEY+':probe');}catch(e){storageOkay=false;try{corruptRaw=localStorage.getItem(KEY)||'';}catch{}readProblem=!!corruptRaw;showStorage(readProblem?'El guardado existente no se pudo validar. Se conserva intacto; descarga el original desde Bitácora antes de restablecer. No se guardarán cambios sobre él.':'El navegador no permite guardar aquí. Puedes utilizar la hoja y exportar un respaldo JSON desde Bitácora antes de cerrar.');}
function showStorage(msg){const n=$('#storage-warning');n.hidden=false;n.textContent=msg;}
function save(){state.updatedAt=new Date().toISOString();if(!readProblem){try{localStorage.setItem(KEY,JSON.stringify(state));storageOkay=true;}catch{storageOkay=false;showStorage('No se pudo guardar en el navegador. Tu estado sigue en esta ventana: exporta un JSON desde Bitácora antes de cerrar.');}}$('#save-status').textContent=readProblem?'Guardado protegido · revisar Bitácora':storageOkay?'Guardado local · '+new Date().toLocaleTimeString('es-MX',{hour:'2-digit',minute:'2-digit'}):'Sin guardado · exporta un respaldo';updateSummary();}
function toast(t){const n=$('#toast');n.textContent=t;n.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('visible'),4200);}
async function confirmChange(title,text){if(busy)return false;busy=true;const d=$('#confirm-dialog');$('#dialog-title').textContent=title;$('#dialog-text').textContent=text;d.returnValue='cancel';d.showModal();return new Promise(resolve=>{d.addEventListener('close',()=>{busy=false;resolve(d.returnValue==='ok');},{once:true});});}
function heading(k,t,p='',extra=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h2>${t}</h2></div>${extra||`<p>${p}</p>`}</div>`;}
function card(title,content,small='',cls=''){return `<article class="card ${cls}"><div class="card-head"><h3>${title}</h3>${small?`<small>${small}</small>`:''}</div>${content}</article>`;}
function option(v,t,selected){return `<option value="${esc(v)}"${v===selected?' selected':''}>${esc(t)}</option>`;}
function select(name,label,options,value){return `<label>${label}<select id="${name}">${options.map(x=>option(x[0],x[1],value)).join('')}</select></label>`;}
function input(id,label,type='text',value='',attrs=''){return `<label>${label}<input id="${id}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`;}
function check(id,label,checked=false){return `<label class="check"><input type="checkbox" id="${id}"${checked?' checked':''}>${label}</label>`;}
function stat(label,value,sub='',accent=false){return `<div class="stat${accent?' accent':''}"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`;}
function spellDetails(s){return `<details class="accordion" data-search="${esc((s.name+' '+s.en+' '+s.text).toLowerCase())}"><summary><span>${esc(s.name)}</span><span class="pill">${s.level?'Nv. '+s.level:'Truco'}${s.concentration?' · C':''}</span></summary><div class="detail-body"><div class="meta"><span class="tag">${esc(s.time)}</span><span class="tag">${s.range?s.range+' pies':'Personal'}</span><span class="tag">${s.id==='disguise'?'Sin espacio · invocación':s.level?'1 espacio de nivel 3':'Sin espacio'}</span></div><p>${esc(s.text)}</p><p class="warning-text">${esc(s.limit)}</p><p class="mini-note"><b>Duración:</b> ${esc(s.duration)}<br><b>Componentes:</b> ${esc(s.components)}<br><b>Concentración:</b> ${s.concentration?'Sí':'No'}</p><p class="mini-note">Procedencia: ${s.id==='hex'||s.id==='agathys'?'Hoja de referencia II y suplemento oficial Princes of the Apocalypse; consulta la auditoría para la diferencia de duración.':'Hoja de referencia II y reglas de 2014; fuentes en Oficialidad.'}</p></div></details>`;}
function resourcesPanel(){return `<div class="resource-title"><span>Puntos de golpe</span><strong>${number(state.hp)} <small>/ ${C.effectiveMax(state)}</small></strong></div><div class="bar"><span style="width:${state.hp===null?0:Math.min(100,state.hp/C.effectiveMax(state)*100)}%"></span></div><p class="resource-sub">${state.hp===null?'Estado actual por registrar':number(state.temp)+' PG temporales · '+(state.tempSource==='agathys'?'Agathys':state.tempSource==='blessing'?'Bendición del Oscuro':state.tempSource==='manual'?'otra fuente':'sin fuente activa')}</p><hr class="thin-rule"><div class="resource-title"><span>Espacios del pacto</span><strong>${number(state.slots)} <small>/ 2</small></strong></div><div class="slot-dots">${[0,1].map(n=>`<span class="slot-dot ${state.slots!==null&&n<state.slots?'filled':''}">✦</span>`).join('')}<span class="muted">Nivel 3 · descanso corto o largo</span></div><hr class="thin-rule"><div class="key-values"><span>Dados de golpe disponibles</span><span>${number(state.hd)} / 5d8</span><span>Concentración</span><span>${state.concentration==='hex'?'Maleficio':state.concentration==='darkness'?'Oscuridad':'Sin registrar efecto activo'}</span><span>Reacción</span><span>${state.reactionAvailable?'Disponible':'Gastada'}</span></div><div class="button-row space-top"><button data-go="mesa" class="small">Abrir mesa ↗</button><button data-go="simulador" class="small">Planificar turno ↗</button></div>`;}
function renderFicha(){
$('#ficha').innerHTML=heading('01 / TABLERO GENERAL','El filo de un pacto','Tu estado, tus ataques y tus conjuros. Todo lo necesario antes de actuar.')+`<div class="stats">${stat('Clase de armadura',13,'Cuero · 11 + DES')}${stat('Puntos de golpe',number(state.hp)+'<span style="display:inline;font-size:1rem"> / '+C.effectiveMax(state)+'</span>','Actuales / máximo',true)}${stat('Iniciativa','+2','1d20 + Destreza')}${stat('Velocidad','30','pies · 9 m')}${stat('Competencia','+3','Nivel 5')}${stat('CD de conjuro',15,'Ataque mágico +7')}</div><div class="grid main-grid"><div class="grid">${card('Características',`<div class="abilities">${D.abilities.map(a=>`<div class="ability"><div class="abbr">${a[1]}</div><div class="score">${a[2]}</div><div class="mod">${signed(Math.floor((a[2]-10)/2))}</div></div>`).join('')}</div><p class="mini-note">Puntuaciones transcritas · modificadores derivados. Carisma gobierna tus conjuros; Destreza gobierna Luto.</p>`,'Valores de la hoja')}${card('Armamento y ataques',`<div class="table-wrap"><table><thead><tr><th>Ataque</th><th>Impacto</th><th>Daño por impacto</th><th>Alcance</th></tr></thead><tbody><tr><td><b>Luto</b><span class="sub">Estoque · arma de pacto</span></td><td class="attack-bonus">+5</td><td>1d8 + 2 perforante<span class="sub">2 ataques al Atacar · Hoja sedienta</span></td><td>5 pies</td></tr><tr><td><b>Daga (×${state.inventory.filter(i=>i.name==='Daga'&&i.kind!=='Referencia · no poseído').reduce((s,i)=>s+i.qty,0)})</b><span class="sub">Sutil · ligera · arrojadiza</span></td><td class="attack-bonus">+5</td><td>1d4 + 2 perforante<span class="sub">Un ataque; Hoja sedienta no se aplica</span></td><td>5 pies /<br>20–60 pies</td></tr><tr><td><b>Descarga sobrenatural</b><span class="sub">Truco · Explosión agonizante</span></td><td class="attack-bonus">+7</td><td>1d10 + 4 fuerza<span class="sub">2 rayos · una tirada por rayo</span></td><td>120 pies</td></tr></tbody></table></div><div class="notice">Con Maleficio sobre el objetivo: <b>+1d6 necrótico por impacto</b>. Luto usa Destreza +2; Val pertenece al Infernal.</div>`,'Una acción')}${card('Salvaciones y habilidades',`<div class="grid cols-2"><div><h4 class="space-bottom">Salvaciones</h4><div class="key-values">${D.saves.map(a=>`<span>${a[0]}${['Sabiduría','Carisma'].includes(a[0])?' <span class="danger-text">◆</span>':''}</span><span>${signed(a[1])}</span>`).join('')}</div><p class="mini-note">◆ Competencia de clase en SAB y CAR.<br>Percepción pasiva <b>11</b> · visión en la oscuridad <b>60 pies</b> · resistencia al fuego.</p></div><div><h4 class="space-bottom">Habilidades registradas</h4><div class="key-values">${D.skills.map(a=>`<span>${a[0]} <small>(${a[1]})</small></span><span>${signed(a[2])}</span>`).join('')}</div></div></div><p class="mini-note">Valores preservados. Perspicacia y Trato con Animales no figuran en las imágenes. Las competencias adicionales están pendientes de procedencia en Oficialidad.</p>`,'Transcripción fiel')}</div><aside class="grid">${card('El pulso de Val',resourcesPanel(),'Recursos actuales')}${card('Magia del pacto',`<div class="spell-list">${D.spells.filter(s=>s.level>0&&s.id!=='disguise').map(s=>`<div class="spell-row"><span class="spell-icon ${s.color}">${s.icon}</span><div><strong>${s.name}</strong><p>${s.time} · ${s.concentration?'Concentración':'Sin concentración'}</p></div><span class="tag">Nv. ${s.level}</span></div>`).join('')}</div><div class="button-row space-top"><button class="small" data-go="reglas">Leer conjuros y condiciones ↗</button></div>`,'6 conocidos')}${card('Siempre a tu alcance',`<div class="spell-list">${D.spells.filter(s=>!s.level||s.id==='disguise').map(s=>`<div class="spell-row"><span class="spell-icon ${s.color}">${s.icon}</span><div><strong>${s.name}</strong><p>${s.id==='disguise'?'Invocación · a voluntad':'Truco · sin espacios'}</p></div></div>`).join('')}</div>`,'3 trucos + invocación')}<div class="quote-card"><blockquote>“No busco redención.<br>Solo quiero que paguen.”</blockquote></div></aside></div>`;
}
function renderLore(){
$('#lore').innerHTML=heading('02 / IDENTIDAD NARRATIVA','Lo que la pérdida deja','Los hechos de esta sección proceden de las imágenes. Las notas son el espacio del jugador para continuar su historia.')+`<div class="quote-card space-bottom"><blockquote>“La venganza también es una forma de libertad.”</blockquote></div><div class="grid main-grid">${card('Retrato de personaje',`<div class="lore-lines"><div><h4>Personalidad</h4><p>Reservada, sarcástica, leal con los suyos y desconfiada.</p></div><div><h4>Ideal</h4><p>La justicia no es un privilegio, es una elección.</p></div><div><h4>Vínculo</h4><p>Un recuerdo que nunca se irá. La pérdida la define. Lleva un amuleto como recuerdo de la persona que perdió; su identidad y relación no están especificadas.</p></div><div><h4>Defecto</h4><p>Su orgullo le impide pedir ayuda.</p></div><div><h4>El pacto y Luto</h4><p>Su patrono se clasifica como El Infernal. Su arma de pacto es un estoque llamado Luto. El nombre de la entidad, las condiciones del pacto y la historia del arma no están documentados.</p></div><div><h4>Apariencia en las ilustraciones</h4><p>Cabello negro largo, cuernos oscuros curvados, indumentaria negra con detalles metálicos y una espada de tonos rojos. Esta es una observación visual; las propiedades mecánicas son las registradas en la hoja.</p></div></div>`,'Datos documentados')}${card('Identidad y límites conocidos',`<div class="key-values"><span>Especie</span><span>Tiefling</span><span>Clase</span><span>Bruja (Warlock) 5</span><span>Patrono</span><span>El Infernal</span><span>Don del pacto</span><span>Pacto de la Hoja</span><span>Trasfondo</span><span>Charlatana</span><span>Alineamiento</span><span>Caótica neutral</span><span>Tamaño</span><span>Mediano</span><span>Campaña</span><span>${esc(state.campaign)||'Por registrar'}</span></div><div class="notice">No se conocen edad, lugar de origen, familia, aliados, nombre del patrono, detalles de la pérdida ni cronología. El nombre de la campaña no se deduce de la ruta de los archivos.</div><p class="muted">“Mi pacto no me da límite, me da acceso. Y eso es mucho más peligroso.”</p>`)}${card('Lo que ocurre después',`<label for="lore-notes">Notas narrativas del jugador · guardado automático<textarea id="lore-notes" data-bind="lore" rows="10" maxlength="100000" placeholder="Registra hechos, decisiones, nuevas relaciones y cambios de Val. Distingue lo vivido en mesa de lo todavía propuesto.">${esc(state.lore)}</textarea></label><p class="mini-note">Estas notas y la bitácora se incluyen en el respaldo JSON. La configuración mecánica permanece en nivel 5.</p>`,'Editable','full')}</div>`;
}
function renderReglas(){
$('#reglas').innerHTML=heading('03 / MANUAL PERSONAL','Conoce tu oscuridad','Abre una regla para consultar sus condiciones. C indica concentración; todas las opciones pertenecen a la configuración de Val.')+`<label class="rule-search">Buscar capacidad o regla<input id="rules-search" type="search" placeholder="Por ejemplo: concentración, Luto, descanso…"></label><div class="grid main-grid"><div><div class="card-head"><h3>Magia, paso a paso</h3><small>10 capacidades</small></div><div class="spells-grid">${D.spells.map(spellDetails).join('')}</div></div><div><div class="card-head"><h3>Las reglas de tu personaje</h3><small>Nivel 5</small></div>${D.rules.map(r=>`<details class="accordion" data-search="${esc((r[0]+' '+r[1]).toLowerCase())}"><summary>${esc(r[0])}</summary><div class="detail-body">${esc(r[1])}</div></details>`).join('')}</div></div><p id="rules-empty" class="no-results" hidden>No hay reglas con esa búsqueda.</p><div class="notice">Las duraciones no avanzan con el reloj del navegador. Confirma el tiempo de ficción con el DM y finaliza los efectos desde Mesa. Las referencias verificadas están en Oficialidad.</div>`;
}
function simForm(){return `<form id="sim-form"><div class="form-grid">${input('sim-distance','Distancia inicial al objetivo (pies)','number',30,'min="0" max="10000" required')}${input('sim-move','Movimiento previsto (pies)','number',0,'min="0" max="10000" required step="1"')}${select('sim-direction','Dirección del movimiento',[['toward','Acercarse'],['away','Alejarse'],['lateral','Lateral · misma distancia']],'toward')}${select('sim-action','Acción principal',Object.entries(C.ACTIONS).map(([k,v])=>[k,v.name]),'blast')}${select('sim-bonus','Acción adicional',Object.entries(C.BONUSES).map(([k,v])=>[k,v.name]),'none')}${select('sim-reaction','Reacción prevista o ejecutada',Object.entries(C.REACTIONS),'none')}${input('sim-target','Nombre del objetivo de Maleficio','text',state.hexTarget,'maxlength="200"')}${select('sim-hex-ability','Maleficio: característica de pruebas',D.abilities.map(x=>[x[1],x[0]]),'FUE')}<div class="full"><div class="grid cols-2">${check('sim-hexOnTarget','El objetivo atacado es el de Maleficio ya activo',false)}${check('sim-previousTargetZero','El objetivo anterior cayó a 0 PG en un turno anterior',false)}</div></div><div class="full"><details class="accordion"><summary>Condiciones, movimiento y componentes</summary><div class="detail-body"><div class="grid cols-2">${check('sim-weaponReady','Luto está en mano',true)}${check('sim-visible','Veo al objetivo o desencadenante',true)}${check('sim-canSpeak','Puedo hablar (componente V)',true)}${check('sim-components','Dispongo de mano libre y componentes o foco válidos',true)}${check('sim-hostileNear','Hay un hostil no incapacitado que me ve a 5 pies')}${check('sim-pathClear','Existe trayectoria válida y no hay cobertura total',true)}${check('sim-offhandReady','Sostengo una daga en cada mano para luchar con dos armas',false)}${check('sim-charmSafe','DM: mi objetivo no es mi encantador',false)}${check('sim-fearSafe','DM: este movimiento no me acerca a la fuente del miedo',false)}${check('sim-difficult','Terreno difícil')}${check('sim-stand','Levantarme si estoy tumbada')}${check('sim-helpPossible','DM: puedo ayudar al aliado en este ataque',true)}${check('sim-hidePossible','DM: puedo esconderme aquí',false)}</div><p class="mini-note">Estas casillas son supuestos de planificación editables. Cobertura total o un objetivo de ubicación desconocida requiere resolver primero la situación con el DM.</p></div></details></div><div class="full space-top" id="teleport-controls" hidden><div class="grid cols-2">${input('sim-teleport','Paso brumoso: pies teleportados','number',30,'min="0" max="30" step="1"')}${select('sim-teleportDirection','Dirección de teleportación',[['toward','Acercarse al objetivo'],['away','Alejarse del objetivo']],'toward')}</div>${check('sim-destinationVisible','El destino está desocupado y lo puedo ver',true)}</div><div class="full space-top" id="reaction-controls" hidden><div class="grid cols-2">${input('sim-reactionDistance','Distancia al desencadenante (pies)','number',30,'min="0" max="10000" step="1"')}${select('sim-reactionTiming','Momento de la reacción',[['other','En el turno de otra criatura'],['same','En mi propio turno']],'other')}${input('sim-enemySpellLevel','Nivel del conjuro enemigo','number',3,'min="1" max="9" step="1"')}</div>${check('sim-reactionTrigger','El desencadenante ocurrió: vi el lanzamiento, o la salida voluntaria sin Retirarse',false)}</div><label class="full space-top">Contexto del turno / desencadenante preparado<textarea id="sim-context" maxlength="2000" rows="2" placeholder="Objetivo, cobertura, aliado al que ayudo, qué preparo y cuándo…"></textarea></label></div></form>`;}
function renderSimulador(){
$('#simulador').innerHTML=heading('04 / PLANIFICADOR DE COMBATE','Elige cómo responder','Planifica sin consumir. Al aplicar, confirma el gasto; el daño se resuelve con dados en la mesa.')+`<div class="preset-row"><button class="preset" data-preset="duel"><strong>El filo de Luto</strong><small>Acercarse · Maleficio · 2 estocadas</small></button><button class="preset" data-preset="blast"><strong>Dos sentencias</strong><small>Maleficio · 2 rayos a distancia</small></button><button class="preset" data-preset="escape"><strong>Entre la niebla</strong><small>Paso brumoso · Descarga</small></button><button class="preset" data-preset="darkness"><strong>Apagar el campo</strong><small>Oscuridad · reserva de Contrahechizo</small></button><button class="preset" data-preset="fire"><strong>Juicio de fuego</strong><small>Bola de fuego · sin acción adicional</small></button></div><div class="sim-grid">${card('Construir el turno',simForm(),'Resolución manual de dados')}<article class="card sim-result"><div class="card-head"><h3>Lectura del turno</h3><span id="sim-badge" class="pill"></span></div><div id="sim-result"></div><div class="sim-actions"><button class="primary" id="apply-turn">Aplicar turno y consumo</button><p class="mini-note">No registra daño infligido. El promedio excluye daño de reacción y represalias. Maleficio o Paso brumoso se resuelven antes de la acción; la segunda daga se usa después. Una reserva de reacción conserva el espacio. Una daga arrojada sale del inventario disponible.</p></div></article></div>`;updateSim();
}
function readSim(){const v=id=>$('#sim-'+id).value,n=id=>{const raw=v(id);return raw.trim()===''?NaN:Number(raw);},b=id=>$('#sim-'+id).checked;return {distance:n('distance'),move:n('move'),direction:v('direction'),action:v('action'),bonus:v('bonus'),reaction:v('reaction'),target:v('target'),hexAbility:v('hex-ability'),teleport:n('teleport'),teleportDirection:v('teleportDirection'),reactionDistance:n('reactionDistance'),reactionTiming:v('reactionTiming'),enemySpellLevel:n('enemySpellLevel'),context:v('context'),...Object.fromEntries(['hexOnTarget','previousTargetZero','weaponReady','visible','canSpeak','components','hostileNear','difficult','stand','helpPossible','hidePossible','destinationVisible','reactionTrigger','pathClear','offhandReady','charmSafe','fearSafe'].map(k=>[k,b(k)]))};}
function updateSim(){if(!$('#sim-form'))return;const i=readSim(),r=C.simulate(state,i);$('#teleport-controls').hidden=i.bonus!=='misty';$('#reaction-controls').hidden=!['counter','opportunity'].includes(i.reaction);const badge=$('#sim-badge');badge.textContent=r.valid?'Combinación válida':'Revisar combinación';badge.className='pill '+(r.valid?'green':'gold');$('#apply-turn').disabled=!r.valid;$('#sim-result').innerHTML=`<div class="result-label">${r.average===null?'SIN DAÑO DIRECTO CALCULABLE':'PROMEDIO DE ACCIÓN + ADICIONAL · CONDICIONADO'}</div><div class="result-number">${r.average===null?'—':number(r.average)}</div><p class="result-label">${esc(r.damage)}</p><ul class="result-list"><li><b>Acción:</b> ${esc(r.action)}</li><li><b>Adicional:</b> ${esc(r.bonus)}</li><li><b>Reacción:</b> ${esc(r.reaction)}</li><li><b>Distancia final:</b> ${number(r.distance)} pies · movimiento ${number(r.moveCost)} / ${number(r.speed)} pies</li><li><b>Espacios:</b> ${r.cost} a consumir · ${r.reserved} reservado · ${number(state.slots)} disponibles</li>${r.details.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${r.errors.length?`<div class="notice danger"><b>No se puede aplicar</b>${r.errors.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`:''}<details class="accordion" open><summary>Restricciones y supuestos</summary><div class="detail-body">${r.warnings.map(t=>`<p>${esc(t)}</p>`).join('')}</div></details>`;}
async function applyTurn(){const i=readSim(),r=C.simulate(state,i);if(!r.valid)return toast(r.errors[0]);const revision=state.updatedAt;if(!await confirmChange('Aplicar este turno',`${r.action}\n${r.bonus}\nConsumir ${r.cost} espacio(s) de nivel 3.${(i.action==='throw'||i.bonus==='offthrow')?' Se retirarán las dagas arrojadas del equipo disponible.':''}\n${r.concentration!==state.concentration?'La concentración pasará a '+(r.concentration==='hex'?'Maleficio':r.concentration==='darkness'?'Oscuridad':'ninguna')+'.':''}\n${r.warnings.some(w=>w.includes('concentración anterior'))?'Terminará tu concentración anterior.':''}\nLos dados y el daño real se resuelven en mesa.`))return;if(state.updatedAt!==revision)return toast('El estado cambió durante la confirmación. Revisa el turno y vuelve a aplicarlo.');let replace=true;if(i.action==='agathys'&&state.temp>0)replace=await confirmChange('Elegir PG temporales','¿Sustituir tus '+state.temp+' PG temporales por 15 de Agathys? Confirmar los reemplaza; Cancelar conserva los actuales. El espacio se consume igualmente al lanzar.');try{state=C.applyTurn(state,i,replace);addLog('Combate','Turno aplicado · '+r.action,`Acción: ${r.action}. Adicional: ${r.bonus}. Reacción: ${r.reaction}. Espacios consumidos: ${r.cost}. ${i.context||''}`,i.bonus==='hex'?'Maleficio sobre '+i.target+'; pruebas de '+i.hexAbility+'.':'');save();refreshAfterMutation();toast('Turno aplicado. El daño real queda pendiente de los dados.');}catch(e){toast(e.message);}}
function renderMesa(){
const initialized=state.hp!==null&&state.temp!==null&&state.slots!==null&&state.hd!==null;
$('#mesa').innerHTML=heading('05 / MESA DE JUEGO','Mantén el pulso','Lleva los recursos reales de la sesión. Registrar un estado no lanza un conjuro ni valida el origen de una capacidad.')+`${!initialized?'<div class="notice">Los recursos actuales no figuran de forma inequívoca en las imágenes. Registra tu estado real o confirma explícitamente que empiezas con recursos completos.</div>':''}<div class="grid main-grid"><div class="grid">${card('Estado actual',`<form id="resources-form"><div class="form-grid">${input('res-hp','PG actuales','number',state.hp,'min="0" max="1000" required')}${input('res-hpMax','Máximo base de PG · hoja: 38','number',state.hpMax,'min="1" max="1000" required')}${input('res-temp','PG temporales actuales','number',state.temp,'min="0" max="1000" required')}${select('res-tempSource','Fuente de los PG temporales',[['none','Sin PG temporales'],['manual','Otra fuente / por identificar'],['agathys','Armadura de Agathys'],['blessing','Bendición del Oscuro']],state.tempSource)}${input('res-slots','Espacios restantes · máximo 2','number',state.slots,'min="0" max="2" required')}${input('res-hd','Dados de golpe restantes · máximo 5','number',state.hd,'min="0" max="5" required')}</div>${check('res-reaction','Reacción disponible hasta usarla o comenzar el siguiente turno',state.reactionAvailable)}<div class="button-row"><button type="submit" class="primary">Registrar estado</button><button type="button" id="full-resources">Confirmar inicio con recursos completos</button></div></form><p class="mini-note">PG máximos registrados: 38. Si los editas, el cambio queda como registro del jugador. Nivel y demás estadísticas siguen en 5. ${state.exhaustion>=4?'El agotamiento reduce el máximo efectivo a '+C.effectiveMax(state)+'.':''}</p>`,'Control manual')}${card('Daño, curación y dados',`<div class="form-grid">${input('damage-amount','Daño recibido antes de resistencia','number',0,'min="0" max="100000" step="1"')}${input('heal-amount','Curación recibida','number',0,'min="0" max="100000" step="1"')}</div><div class="grid cols-2">${check('damage-fire','El daño es de fuego: aplicar resistencia')}${check('damage-melee','Procede de un impacto cuerpo a cuerpo')}</div><div class="button-row"><button id="damage-button">Aplicar daño</button><button id="heal-button">Aplicar curación</button><button id="blessing-button">Bendición: reduje un hostil a 0 PG</button></div><div id="damage-result" role="status" class="mini-note"></div><div class="input-row space-top">${input('con-roll','Concentración: resultado natural del d20','number','','min="1" max="20" step="1"')}${input('con-dc','CD (máx. de 10 o daño / 2)','number',state.pendingConcentrationDC||10,'min="10" max="50000" step="1"')}<button id="concentration-roll">Resolver con +2</button></div><hr class="thin-rule"><div class="input-row">${input('hd-roll','Dado de golpe: resultado real del d8','number','','min="1" max="8" step="1"')}<button id="spend-hd">Gastar 1d8 y curar +2</button></div><p class="mini-note">Gasta dados al final de un descanso corto, uno por vez. No se hacen tiradas aleatorias ocultas.</p>`)}${card('Descansos y turno',`${check('rest-food','Comí y bebí lo suficiente para reducir agotamiento',true)}<div class="button-row"><button id="short-rest">Descanso corto</button><button id="long-rest">Descanso largo</button><button id="next-turn" class="primary">Comenzar siguiente turno</button></div><p class="mini-note">Corto: recupera 2 espacios tras al menos 1 hora; PG y dados se registran por separado. Largo: PG, espacios, hasta 2 dados y un nivel de agotamiento si comiste y bebiste. No elimina todas las condiciones.</p><div class="notice">${state.turnApplied?'Turno '+state.round+' aplicado. Inicia el siguiente al comenzar tu turno en combate.':'Turno '+state.round+' disponible para planificar.'} La reacción se recupera al comienzo del siguiente turno.</div><p class="mini-note">Último descanso largo registrado: ${state.lastLongRest?esc(new Date(state.lastLongRest).toLocaleString('es-MX')):'ninguno'}. La fecha registra cuándo usaste el control. El requisito de 24 horas se confirma en tiempo de ficción, con el DM; no se mide con el reloj real del navegador.</p>`)}${card('Inventario de Val',`<div id="inventory-list">${renderInventory()}</div><hr class="thin-rule"><form id="add-item"><div class="form-grid">${input('item-name','Nuevo objeto','text','','maxlength="200" required')}${input('item-qty','Cantidad','number',1,'min="0" max="99999" step="1" required')}${select('item-kind','Procedencia',[['Poseído · añadido','Poseído · añadido por jugador'],['Personalizado','Personalizado · registra autorización'],['Referencia · no poseído','Referencia · no poseído']],'Poseído · añadido')}${select('item-icon','Icono de categoría',[['bag','Equipo'],['sword','Arma'],['dagger','Daga'],['armor','Armadura'],['focus','Foco'],['book','Libro'],['amulet','Amuleto']],'bag')}</div><label>Descripción / origen / autorización<textarea id="item-notes" maxlength="5000" rows="2"></textarea></label><button type="submit">Añadir al inventario</button></form><p class="mini-note">Monedas, pesos, capacidades de carga y consumibles no están documentados. Puedes anotarlos sin que la app invente cantidades. Cambiar el nombre Luto o Daga desvincula ese objeto del ataque configurado.</p>`,'Editable y persistente')}</div><aside class="grid">${card('Recursos en vivo',resourcesPanel())}${card('Concentración y posición',`${state.pendingConcentrationDC!==null?'<div class="notice danger">Prueba de concentración pendiente: CON +2, CD '+state.pendingConcentrationDC+'. Resuélvela antes del siguiente daño o turno.</div>':''}${select('concentration','Concentración activa',[['none','Ninguna'],['hex','Maleficio'],['darkness','Oscuridad']],state.concentration)}${input('hex-target','Objetivo de Maleficio','text',state.hexTarget,'maxlength="200"')}<div class="button-row"><button id="save-concentration">Registrar efecto ya activo</button><button id="end-agathys" class="small">Finalizar Agathys</button></div><label class="space-top">Posición táctica<input data-bind="position" maxlength="1000" value="${esc(state.position)}" placeholder="Cobertura, altura, aliados, distancia…"></label>${input('round','Ronda / turno de referencia','number',state.round,'min="1" max="999999" step="1"')}<p class="mini-note">Registrar un efecto ya lanzado no consume espacios. Para lanzarlo ahora, utiliza el simulador. Fin de Agathys elimina los PG temporales que procedan de ese conjuro.</p>`)}${card('Condiciones',`<div class="conditions">${C.CONDITIONS.map(c=>`<label class="condition"><input type="checkbox" data-condition="${c}"${state.conditions.includes(c)?' checked':''}>${c}</label>`).join('')}</div>${select('exhaustion','Nivel de agotamiento',Array.from({length:7},(_,n)=>[String(n),n===0?'0 · Ninguno':n===1?'1 · Desventaja en pruebas':n===2?'2 · Velocidad a la mitad':n===3?'3 · Desventaja en ataques y salvaciones':n===4?'4 · Máximo de PG a la mitad':n===5?'5 · Velocidad 0':'6 · Muerte']),String(state.exhaustion))}<p class="condition-summary">${state.hp===0?'A 0 PG se considera inconsciente automáticamente. ':''}Incapacitada, aturdida, paralizada, petrificada o inconsciente termina concentración. Agotamiento y condiciones se guardan; el DM resuelve inmunidades, fuentes y duración.</p>`)}${card('Salvaciones de muerte',`<div class="death-controls">${input('death-success','Éxitos','number',state.deathSuccess,'min="0" max="3" step="1"')}${input('death-fail','Fallos','number',state.deathFail,'min="0" max="3" step="1"')}</div><div class="button-row"><button id="save-death">Registrar</button><button id="death-20">20 natural: recuperar 1 PG</button></div><p class="mini-note">${state.deathFail>=3?'Tres fallos: muerte registrada.':state.deathSuccess>=3?'Tres éxitos: estable a 0 PG.':'Registra las tiradas reales y las consecuencias indicadas por el DM.'} Un 1 natural suma dos fallos. Daño crítico a 0 PG: añade un segundo fallo manualmente.</p>`)}${card('Notas de sesión',`<label>Guardado automático<textarea data-bind="notes" rows="6" maxlength="50000" placeholder="Iniciativa enemiga, duraciones, objetivos pendientes…">${esc(state.notes)}</textarea></label>`)}${card('Biblioteca de equipo',`<div class="library">${[['sword','Estoque'],['dagger','Daga'],['armor','Cuero'],['focus','Foco'],['book','Libro'],['bag','Bolsa'],['amulet','Amuleto']].map(x=>`<figure><img src="assets/icono/inventario/${x[0]}.svg" alt="Icono ilustrativo de ${x[1]}"><figcaption>${x[1]}</figcaption></figure>`).join('')}</div><p class="mini-note">Iconos originales de categoría, únicamente ilustrativos. La posesión y cantidad las determina el inventario.</p>`,'Referencia visual')}</aside></div>`;
}
function renderInventory(){return state.inventory.length?state.inventory.map(i=>`<div class="inventory-item" data-item="${esc(i.id)}"><img src="assets/icono/inventario/${i.icon}.svg" alt=""><div><label>Objeto<input data-item-field="name" value="${esc(i.name)}" maxlength="200" required aria-label="Nombre del objeto"></label><label>Descripción<textarea data-item-field="notes" maxlength="5000" rows="2">${esc(i.notes)}</textarea></label><label>Procedencia<select data-item-field="kind">${['Poseído · hoja','Poseído · añadido','Personalizado','Referencia · no poseído'].map(k=>option(k,k,i.kind)).join('')}</select></label></div><div><label>Cantidad<input data-item-field="qty" type="number" min="0" max="99999" step="1" value="${i.qty}"></label><button class="small delete" data-delete-item="${esc(i.id)}">Quitar</button></div></div>`).join(''):'<p class="empty">No hay objetos registrados.</p>';}
function renderBitacora(){
$('#bitacora').innerHTML=heading('06 / MEMORIA Y RESPALDOS','Que nada se pierda','Guarda lo vivido y conserva copias de tu personaje. Este archivo no envía información a ningún servidor.')+`<div class="grid main-grid"><div class="grid">${card('Escribir un registro',`<form id="log-form"><div class="form-grid">${input('log-date','Fecha','date',localDate(),'required')}${input('log-session','Sesión / capítulo','text','','maxlength="120"')}${select('log-type','Tipo de acontecimiento',['Combate','Exploración','Relación','Descubrimiento','Recompensa','Decisión del DM','Otro'].map(x=>[x,x]),'Exploración')}${input('log-title','Título','text','','maxlength="200" required')}<label class="full">Lo ocurrido<textarea id="log-body" maxlength="30000" rows="4" required></textarea></label><label class="full">Continuidad · consecuencias, vínculos, pistas<textarea id="log-continuity" maxlength="10000" rows="2"></textarea></label></div><button type="submit" class="primary">Guardar en la bitácora</button></form>`)}${card('Historial',`<label class="space-bottom">Buscar en todos los registros<input id="log-search" type="search" placeholder="Título, sesión, tipo, contenido o continuidad…"></label><div id="log-history">${renderLogs()}</div>`,'<span id="log-count">'+state.logs.length+' entradas</span>')}</div><aside class="grid">${card('Tu archivo de campaña',`<label>Campaña · opcional<input data-bind="campaign" value="${esc(state.campaign)}" maxlength="160" placeholder="Nombre confirmado de tu campaña"></label><div class="button-row"><button id="export-json" class="primary">Exportar respaldo JSON</button><button id="export-text">Exportar bitácora TXT</button><button id="copy-state">Copiar estado para compartir</button></div><textarea id="copy-fallback" readonly hidden aria-label="Estado para copiar manualmente"></textarea><p class="mini-note">El JSON incluye recursos, inventario, concentración, condiciones, notas, lore, bitácora, campaña y versión. No incluye las imágenes: conserva también la carpeta de la hoja.</p>`)}${card('Restaurar un respaldo',`<label>Seleccionar archivo JSON<input id="import-file" class="file-input" type="file" accept=".json,application/json"></label><p class="mini-note">Solo se aceptan respaldos de Val Draven, nivel 5, esquema v1. Se valida el archivo completo antes de pedir confirmación. Al reemplazar se descarga una copia del estado anterior.</p><div class="notice">Abre siempre la misma copia de la hoja para conservar el almacenamiento del navegador. Otra carpeta, navegador o equipo puede tener un estado diferente. Usa JSON para trasladarlo.</div>`)}${card('Gestión de datos',`${readProblem?'<button id="export-corrupt">Descargar guardado original sin modificar</button><p class="mini-note">Conserva esta copia para recuperar tus datos antes de restablecer.</p>':''}<button id="reset-state" class="danger">Restablecer datos de Val</button><p class="mini-note">Requiere confirmación y descarga un respaldo antes de restablecer. Solo afecta a la clave de almacenamiento de esta configuración de Val; otros personajes no se modifican.</p><p class="mini-note">Identificador: ${C.ID}<br>Esquema: ${C.VERSION}<br>Último cambio: ${esc(new Date(state.updatedAt).toLocaleString('es-MX'))}</p>`)}<div class="quote-card"><blockquote>“El conocimiento también es un arma.<br>Y yo siempre vuelvo a empuñarla.”</blockquote></div></aside></div>`;
}
function renderLogs(q=''){const matches=state.logs.filter(l=>[l.title,l.body,l.session,l.type,l.continuity,l.date].join(' ').toLowerCase().includes(q.toLowerCase()));return matches.length?matches.slice().reverse().map(l=>`<article class="entry"><div class="entry-meta">${esc(l.date)} / ${esc(l.type)} ${l.session?' / '+esc(l.session):''}</div><h3>${esc(l.title)}</h3><p class="entry-text">${esc(l.body)}</p>${l.continuity?`<p class="entry-text space-top"><b>Continuidad:</b> ${esc(l.continuity)}</p>`:''}<button class="small delete" data-delete-log="${esc(l.id)}">Eliminar entrada</button></article>`).join(''):`<div class="empty">${q?'No hay registros con esa búsqueda.':'La bitácora está en blanco. Tu primera entrada empieza aquí.'}</div>`;}
function auditTable(rows){return `<div class="table-wrap"><table class="audit-table"><thead><tr><th>Elemento</th><th>Regla / procedencia</th><th>Configuración utilizada</th><th>Estado</th></tr></thead><tbody>${rows.map(r=>'<tr>'+r.map((v,i)=>`<td>${i===3?`<span class="pill ${v==='Oficial'?'green':v==='Narrativo'?'':'gold'}">${v}</span>`:v}</td>`).join('')+'</tr>').join('')}</tbody></table></div>`;}
function renderOficialidad(){
$('#oficialidad').innerHTML=heading('07 / PROCEDENCIA Y AUDITORÍA','Las reglas y la historia','Esta sección documenta el origen de la configuración. No cambia los valores registrados ni consume recursos.')+`<div class="notice">Edición identificada explícitamente en la imagen 02: <b>D&D 5e 2014</b>. «Elección de build» indica una opción oficial elegida, no una regla casera. No hay modificaciones del DM ni homebrew mecánico aprobados en los materiales recibidos.</div><div class="grid">${card('A · Identidad, características y trasfondo',auditTable([
['Tiefling / Bruja 5 / El Infernal','Especie y clase oficiales de 2014; SRD 5.1: Tiefling y Warlock.','Transcritos de ambas imágenes.','Oficial'],
['Características y estadísticas','FUE 8, DES 14, CON 14, INT 10, SAB 12, CAR 18. Competencia +3 a nivel 5.','CA 13; PG registrados 38; iniciativa +2; velocidad 30 pies. Modificadores, ataque +7 y CD 15 derivados y coincidentes.','Hoja registrada'],
['PG actuales y máximos','La imagen muestra «PG 38» sin separar actuales de máximos.','38 como máximo de referencia editable; actuales por registrar. Coincide con 8+2 + 4×(5+2), pero no se afirma cómo se obtuvieron.','Pendiente'],
['Charlatana','Trasfondo oficial de 2014 declarado en la hoja. Sin documento completo de elecciones o equipo de trasfondo.','Se conserva el nombre. Herramientas, identidad falsa y objetos de trasfondo no registrados no se incorporan como posesiones.','Oficial'],
['Salvaciones','Bruja: competencia en Sabiduría y Carisma.','−1, +2, +2, +0, +4, +7. El círculo de Fuerza es ambiguo; su valor −1 coincide con no competente.','Hoja registrada'],
['Idiomas','La hoja solo dice «hablante de idiomas adicionales según campaña».','No se inventan idiomas ni se activan bonificadores.','Pendiente']
]))}${card('B · Armamento y equipo',auditTable([
['Luto','Estoque oficial, sutil; Pacto de la Hoja y Hoja sedienta oficiales.','+5, 1d8+2 perforante; dos ataques al Atacar con Luto. Es mágica para superar resistencia, sin +1 inventado.','Oficial'],
['Cuero y dagas','Armadura de cuero: 11 + DES. Daga: 1d4, sutil, ligera, arrojadiza 20/60 pies.','Cuero CA 13; dos dagas. Alcances y propiedades completados desde reglas.','Oficial'],
['Foco, ropa, bolsa, libro, amuleto','Objetos registrados en la imagen 01.','Sin propiedades mágicas extra. El libro no concede rituales o preparación de mago.','Hoja registrada'],
['Nombre e imagen de Luto','Descripción propia del personaje; no implica bonificaciones adicionales.','Arte aportado por el usuario. Iconos de equipo originales de categoría.','Narrativo']
]))}${card('C · Rasgos, competencias e invocaciones',auditTable([
['Tres invocaciones','Hoja sedienta requiere bruja 5 y Pacto de la Hoja; Explosión agonizante requiere Descarga; Máscara de muchos rostros es una opción oficial.','Cumple los prerrequisitos documentados. Hoja sedienta no se aplica a dagas u oportunidades.','Oficial'],
['Bendición del Oscuro','Al reducir tú una criatura hostil a 0 PG: Carisma + nivel de bruja en PG temporales.','9 PG temporales, sin acumular; se confirma el hecho.','Oficial'],
['Visión en la oscuridad / resistencia','Rasgos tiefling de 2014: 60 pies y resistencia al fuego.','Activos. La resistencia redondea daño hacia abajo. Visión no atraviesa Oscuridad mágica.','Oficial'],
['Competencias en habilidades','La hoja muestra ocho bonos compatibles con competencia simple: Acrobacias, Engaño, Intimidación, Investigación, Juego de Manos, Persuasión, Sigilo y Supervivencia. La clase aporta dos y Charlatana dos; no se documentan otras fuentes.','Se conservan todos los bonos registrados sin retirarlos. El origen del conjunto excedente requiere aclaración. Perspicacia y Trato con Animales no están registrados.','Pendiente'],
['Sentidos agudizados','Mencionado sin descripción ni bonificador; no es un rasgo estándar de tiefling.','Texto conservado en auditoría; sin modificador mecánico inventado.','Pendiente']
]))}${card('D · Magia documentada',auditTable([
['Tres trucos y seis conocidos','La progresión de bruja 5 permite tres trucos, seis conjuros conocidos y dos espacios de nivel 3.','Los nueve de las imágenes; Disfrazarse se añade como lanzamiento de invocación.','Oficial'],
['Bola de fuego','Conjuro elegible por la lista ampliada del Infernal al nivel correspondiente. No se aprende automáticamente.','La hoja sí lo elige como conocido. 8d6, DES CD 15.','Oficial'],
['Maleficio: duración','Imagen 02: hasta 1 hora. La regla de 2014 amplía hasta 8 horas con espacio de nivel 3 o 4 (suplemento oficial Princes of the Apocalypse, entrada Hex).','Registro original conservado. Se muestran ambas duraciones, sin temporizador o caducidad automática que elija una por el DM.','Diferencia documentada'],
['Armadura de Agathys','Configuración explícita en imagen 02 y suplemento oficial Princes of the Apocalypse (entrada Armor of Agathys): acción, 1 hora, 15 PG temporales y 15 frío al nivel 3. Interacción con PG temporales verificada en Sage Advice.','Se usa la configuración de la hoja, sin reemplazarla por la versión 2024 de acción adicional. Componentes según regla 2014; no se atribuye al SRD, que no incluye este conjuro.','Oficial'],
['Magia racial de tiefling','El tiefling estándar de 2014 incluye Legado infernal; la subraza o variante no se especifica.','Taumaturgia y Reprensión infernal no están registrados. Oscuridad figura como conocida de bruja. No se añade lanzamiento racial gratuito ni recursos raciales sin confirmar.','Pendiente']
]))}${card('E · Contenido exclusivo del personaje',`<p>Val Draven, el nombre Luto, sus frases, su personalidad, el ideal de justicia, la pérdida y el amuleto pertenecen a su narrativa documentada. No se les atribuyen efectos numéricos. Las ilustraciones son los dos PNG aportados; no se generó una apariencia alternativa.</p><p class="mini-note">No hay homebrew mecánico o autorizaciones del DM documentados. Los objetos que añadas como Personalizado deben describir su origen y aprobación. Las decisiones pueden registrarse como «Decisión del DM» en Bitácora; no se convierten en reglas activas por escribirlas aquí.</p>`)}${card('F · Pendientes y datos ausentes',`<div class="lore-lines"><div><h4>Antes de jugar</h4><p>Registrar PG actuales, temporales, dados disponibles, espacios, efectos y condiciones. Confirmar el máximo de PG si «38» era un valor actual diferente del máximo. Registrar el nombre de la campaña si se conoce.</p></div><div><h4>Consultar con el DM cuando corresponda</h4><p>Origen de competencias adicionales; significado de Sentidos agudizados; subraza o variante tiefling y magia racial; duración acordada de Maleficio; idiomas concretos y cualquier propiedad adicional de Luto.</p></div><div><h4>Sin datos suficientes</h4><p>Monedas, pesos, munición o consumibles, herramientas, historia ampliada, familia, relaciones concretas y nombre del patrono. Permanecen sin inventar.</p></div></div>`)}${card('Fuentes y materiales',`<div class="sources"><p><b>Materiales primarios del personaje:</b> 01-ValDravenNvl-5.png y 02-ValDravenNvl-5.png; prompt maestro proporcionado. No se recibió HTML de referencia ni historia adicional.</p><p><b>Reglas consultadas:</b> <a href="https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1.pdf" target="_blank" rel="noopener">SRD 5.1 · CC BY 4.0</a>; <a href="https://www.dndbeyond.com/sources/dnd/basic-rules-2014/classes" target="_blank" rel="noopener">clases de 2014</a>; <a href="https://www.dndbeyond.com/sources/dnd/basic-rules-2014/spellcasting" target="_blank" rel="noopener">lanzamiento de conjuros</a>; <a href="https://www.dndbeyond.com/sources/dnd/basic-rules-2014/combat" target="_blank" rel="noopener">combate</a>; <a href="https://www.dndbeyond.com/sources/dnd/basic-rules-2014/adventuring" target="_blank" rel="noopener">descansos</a>; <a href="https://www.dndbeyond.com/sources/dnd/basic-rules-2014/spells" target="_blank" rel="noopener">conjuros SRD</a>; <a href="https://media.wizards.com/2015/downloads/dnd/PrincesApocalypse_AdvSupplementv1.0_PrinterFriendly.pdf" target="_blank" rel="noopener">suplemento oficial Princes of the Apocalypse · Hex y Armor of Agathys</a>; <a href="https://www.dndbeyond.com/sources/dnd/sac/sage-advice-compendium" target="_blank" rel="noopener">Sage Advice · interacción de Agathys y Bendición</a>. Estos enlaces de consulta necesitan conexión; el contenido de la app ya está incluido localmente.</p><p>Resúmenes en español redactados para esta hoja; sin texto íntegro de manuales. No se declara una página de manual no verificada.</p><p class="mini-note">This work includes material taken from the System Reference Document 5.1 (“SRD 5.1”) by Wizards of the Coast LLC and available at https://dnd.wizards.com/resources/systems-reference-document. The SRD 5.1 is licensed under the Creative Commons Attribution 4.0 International License available at https://creativecommons.org/licenses/by/4.0/legalcode. Adaptaciones: resúmenes y traducción al español, interfaz y cálculos para Val Draven. Arte de personaje aportado por el usuario, fuera de esta atribución.</p></div>`)}<details class="accordion"><summary>Consultar las dos hojas originales</summary><div class="detail-body reference-grid"><figure><a href="assets/imagen/val-draven-ficha.png" target="_blank" rel="noopener"><img src="assets/imagen/val-draven-ficha.png" alt="Hoja original 01 completa" loading="lazy"></a><figcaption>01 · Ficha y equipo. Pulsa para ampliar.</figcaption></figure><figure><a href="assets/imagen/val-draven-referencia.png" target="_blank" rel="noopener"><img src="assets/imagen/val-draven-referencia.png" alt="Hoja original 02 completa" loading="lazy"></a><figcaption>02 · Referencia de conjuros y combate.</figcaption></figure></div></details></div>`;
}
function updateSummary(){$('#session-state').textContent=state.hp===null?'Estado de mesa por registrar':'Turno '+state.round+' · '+(state.turnApplied?'aplicado':'disponible');$('#mini-resources').textContent='PG '+number(state.hp)+'/'+C.effectiveMax(state)+' · Temporales '+number(state.temp)+' · Pacto '+number(state.slots)+'/2 · '+(state.concentration==='hex'?'Maleficio':state.concentration==='darkness'?'Oscuridad':'Sin concentración');}
function renderAll(){renderFicha();renderLore();renderReglas();renderSimulador();renderMesa();renderBitacora();renderOficialidad();updateSummary();}
function refreshAfterMutation(){renderFicha();renderMesa();renderBitacora();updateSim();updateSummary();}
function setTab(tab,focus=false){if(!['ficha','lore','reglas','simulador','mesa','bitacora','oficialidad'].includes(tab))tab='ficha';activeTab=tab;$$('[role=tabpanel]').forEach(n=>n.hidden=n.id!==tab);$$('[role=tab]').forEach(n=>{const selected=n.dataset.tab===tab;n.setAttribute('aria-selected',String(selected));n.tabIndex=selected?0:-1;});if(focus)$('#tab-'+tab).focus();try{history.replaceState(null,'','#'+tab);}catch{}if(tab==='simulador')updateSim();}
function addLog(type,title,body,continuity=''){if(state.logs.length>=3000){toast('Bitácora al límite de 3000 entradas. Exporta y elimina entradas antiguas para continuar.');return;}state.logs.push({id:uid(),date:localDate(),session:'Turno '+state.round,type,title,body,continuity});}
function filename(suffix,ext){const slug=x=>x.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').slice(0,80);return 'ValDraven'+(state.campaign?'_'+slug(state.campaign):'')+'_'+suffix+'_'+localDate()+'.'+ext;}
function download(content,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportJSON(suffix='respaldo'){download(JSON.stringify(state,null,2),filename(suffix,'json'),'application/json');}
function shareText(){return `VAL DRAVEN · Tiefling · Bruja 5 / El Infernal · D&D 2014\nCampaña: ${state.campaign||'por registrar'}\nCA 13 | Iniciativa +2 | Velocidad base 30 pies\nPG ${number(state.hp)}/${C.effectiveMax(state)} | Temporales ${number(state.temp)} (${state.tempSource})\nPacto nivel 3: ${number(state.slots)}/2 | Dados ${number(state.hd)}/5d8\nConcentración: ${state.concentration==='hex'?'Maleficio sobre '+(state.hexTarget||'objetivo por registrar'):state.concentration==='darkness'?'Oscuridad':'ninguna registrada'}\nReacción: ${state.reactionAvailable?'disponible':'gastada'} | Turno ${state.round}\nCondiciones: ${C.effectiveConditions(state).join(', ')||'ninguna registrada'} | Agotamiento: ${state.exhaustion}\nPosición: ${state.position||'por registrar'}\nNotas: ${state.notes||'—'}`;}
function validInt(id,min,max){const n=$(id);if(!n||n.value.trim()===''||!Number.isInteger(Number(n.value))||Number(n.value)<min||Number(n.value)>max)throw new Error('Introduce un entero entre '+min+' y '+max+' en «'+(n?.closest('label')?.childNodes[0]?.textContent?.trim()||id)+'».');return Number(n.value);}
function clearConIfIncap(){if(C.effectiveConditions(state).some(c=>['Incapacitada','Paralizada','Petrificada','Aturdida','Inconsciente'].includes(c))||state.exhaustion>=6){state.concentration='none';state.hexTarget='';state.pendingConcentrationDC=null;}}
async function receiveDamage(){try{const n=validInt('#damage-amount',1,100000),fire=$('#damage-fire').checked,melee=$('#damage-melee').checked;if(!await confirmChange('Aplicar daño recibido',`${n} de daño${fire?' de fuego (se reduce a '+Math.floor(n/2)+')':''}. Se absorberá primero con PG temporales. Confirma que la tirada ya se resolvió.`))return;const r=C.receiveDamage(state,n,fire,melee);state=r.state;lastDamageDC=r.concentrationDC;save();refreshAfterMutation();$('#damage-result').textContent=`Daño tras resistencia: ${r.damage}. Absorbido por temporales: ${r.absorption}.${r.retaliation?' El atacante recibe '+r.retaliation+' de frío de Agathys (si el impacto cumple sus condiciones).':''}${r.concentrationDC?' Resuelve ahora CON +2, CD '+r.concentrationDC+'.':''}${state.hp===0?' A 0 PG: inconsciente, concentración terminada.':''}`;toast(r.concentrationDC?'Daño registrado. Falta resolver concentración.':'Daño registrado.');}catch(e){toast(e.message);}}
async function heal(){try{if(state.hp===null)throw new Error('Registra tus PG primero.');if(state.deathFail>=3||state.exhaustion>=6)throw new Error('La muerte registrada requiere resolución del DM; la curación normal no la revierte.');const n=validInt('#heal-amount',1,100000);state.hp=Math.min(C.effectiveMax(state),state.hp+n);if(state.hp>0){state.deathFail=0;state.deathSuccess=0;}save();refreshAfterMutation();toast('Curación registrada.');}catch(e){toast(e.message);}}
async function blessing(){if(state.temp===null)return toast('Registra tus PG temporales primero.');if(!await confirmChange('Bendición del Oscuro','Confirma que Val redujo una criatura hostil a 0 PG. Aceptar reemplaza los '+state.temp+' PG temporales actuales por 9; no se suman.'+(state.agathysActive?' Esto termina la represalia de Agathys.':'')))return;state.temp=C.CFG.cha+C.CFG.level;state.tempSource='blessing';state.agathysActive=false;save();refreshAfterMutation();toast('9 PG temporales de Bendición del Oscuro.');}
async function shortRest(){if(!await confirmChange('Finalizar descanso corto','Confirma al menos 1 hora de descanso válido. Recuperarás los 2 espacios de pacto. Los PG, dados de golpe, condiciones y concentración se mantienen; revisa duraciones en tiempo de ficción.'))return;state.slots=2;addLog('Otro','Descanso corto','Descanso corto confirmado. Dos espacios de pacto recuperados.');save();refreshAfterMutation();toast('Espacios recuperados. Puedes gastar dados de golpe.');}
async function longRest(){try{const food=$('#rest-food').checked;C.longRest(state,Date.now(),food);if(!await confirmChange('Finalizar descanso largo','Confirma 8 horas de descanso válido, al menos 1 PG al inicio, ningún otro beneficio de descanso largo en 24 horas en tiempo de ficción. La recuperación de agotamiento depende de la casilla de comida y bebida. Recuperarás PG, 2 espacios y hasta 2 dados; terminarán PG temporales y concentraciones de duración menor. Las demás condiciones se conservan.'))return;state=C.longRest(state,Date.now(),food);addLog('Otro','Descanso largo','Descanso largo confirmado. PG y espacios restaurados, hasta dos dados recuperados.'+(food?' Agotamiento reducido un nivel si lo había.':' No se reduce agotamiento por falta de comida/bebida.'));save();refreshAfterMutation();toast('Descanso largo registrado.');}catch(e){toast(e.message);}}
function spendHD(){try{if(state.hp===null||state.hd===null)throw new Error('Registra PG y dados disponibles primero.');if(state.hd<1)throw new Error('No quedan dados de golpe.');if(state.hp===0||state.deathFail>=3)throw new Error('Resuelve con el DM el estado a 0 PG antes de gastar dados.');const roll=validInt('#hd-roll',1,8);state.hd--;state.hp=Math.min(C.effectiveMax(state),state.hp+Math.max(0,roll+C.CFG.con));save();refreshAfterMutation();toast('1d8 gastado: '+(roll+C.CFG.con)+' PG de curación, hasta el máximo.');}catch(e){toast(e.message);}}
function resolveConcentration(){try{if(state.concentration==='none')throw new Error('No hay concentración activa registrada.');const roll=validInt('#con-roll',1,20),dc=validInt('#con-dc',10,50000),total=roll+C.CFG.con;const fail=total<dc;if(fail){state.concentration='none';state.hexTarget='';}lastDamageDC=null;state.pendingConcentrationDC=null;save();refreshAfterMutation();toast('CON '+roll+' +2 = '+total+' contra CD '+dc+': '+(fail?'concentración terminada.':'mantienes concentración.')+(state.exhaustion>=3?' Asegúrate de haber tirado con desventaja por agotamiento.':''));}catch(e){toast(e.message);}}
async function newTurn(){if(!await confirmChange('Comenzar siguiente turno','Confirma que empieza tu siguiente turno: recuperarás acción, acción adicional, movimiento y reacción. Los espacios, PG y concentraciones se mantienen.'))return;state.round++;state.turnApplied=false;state.reactionAvailable=true;save();refreshAfterMutation();toast('Nuevo turno disponible.');}
async function importJSON(file){if(!file)return;try{if(file.size>8*1024*1024)throw new Error('El archivo supera el límite de 8 MB.');const candidate=C.validateState(JSON.parse(await file.text()));if(!await confirmChange('Reemplazar el estado de Val',`Respaldo de ${new Date(candidate.updatedAt).toLocaleString('es-MX')}.\n${candidate.logs.length} entradas y ${candidate.inventory.length} objetos.\nSe descargará una copia del estado anterior y luego se reemplazará. Las imágenes y la configuración de nivel 5 no cambian.`))return;if(readProblem&&corruptRaw)download(corruptRaw,filename('guardado_original','json'),'application/json');else exportJSON('antes_de_importar');state=candidate;readProblem=false;$('#storage-warning').hidden=true;save();renderAll();setTab(activeTab);toast('Respaldo validado y restaurado.');}catch(e){toast('Importación rechazada: '+e.message);}finally{if($('#import-file'))$('#import-file').value='';}}
async function resetState(){if(!await confirmChange('Restablecer esta hoja','Se descargará una copia y se borrarán los recursos registrados, notas, inventario editado y bitácora de esta configuración de Val. Los recursos actuales volverán a quedar pendientes. Otros personajes no se modifican.'))return;if(readProblem&&corruptRaw)download(corruptRaw,filename('guardado_original','json'),'application/json');else exportJSON('antes_de_restablecer');state=C.defaultState(D);readProblem=false;$('#storage-warning').hidden=true;save();renderAll();setTab(activeTab);toast('Datos de Val restablecidos.');}
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-tab]');if(tab){setTab(tab.dataset.tab);return;}const go=e.target.closest('[data-go]');if(go){setTab(go.dataset.go);$('#tab-'+go.dataset.go).scrollIntoView({block:'nearest',inline:'center'});return;}const pre=e.target.closest('[data-preset]');if(pre){applyPreset(pre.dataset.preset);return;}const del=e.target.closest('[data-delete-item]');if(del){if(await confirmChange('Quitar objeto','Se eliminará el objeto del inventario de Val.')){state.inventory=state.inventory.filter(x=>x.id!==del.dataset.deleteItem);save();refreshAfterMutation();}return;}const log=e.target.closest('[data-delete-log]');if(log){if(await confirmChange('Eliminar entrada','Se eliminará permanentemente esta entrada de la bitácora local. Puedes exportar un respaldo antes.')){state.logs=state.logs.filter(x=>x.id!==log.dataset.deleteLog);save();renderBitacora();}return;}
const actions={'apply-turn':applyTurn,'damage-button':receiveDamage,'heal-button':heal,'blessing-button':blessing,'short-rest':shortRest,'long-rest':longRest,'spend-hd':spendHD,'concentration-roll':resolveConcentration,'next-turn':newTurn,'export-json':()=>exportJSON(),'export-text':()=>download(`BITÁCORA · VAL DRAVEN\nCampaña: ${state.campaign||'Sin registrar'}\n\n`+state.logs.map(l=>`${l.date} | ${l.session} | ${l.type}\n${l.title}\n${l.body}\nContinuidad: ${l.continuity||'—'}\n`).join('\n---\n\n'),filename('bitacora','txt')),'reset-state':resetState,'export-corrupt':()=>download(corruptRaw,filename('guardado_original','json'),'application/json'),'copy-state':async()=>{try{await navigator.clipboard.writeText(shareText());toast('Estado copiado.');}catch{const t=$('#copy-fallback');t.hidden=false;t.value=shareText();t.focus();t.select();toast('Selecciona y copia este texto con Ctrl+C.');}},'full-resources':async()=>{if(await confirmChange('Confirmar recursos completos','Confirma que Val empieza con '+C.effectiveMax(state)+' PG, 0 temporales, 5 dados de golpe y 2 espacios de nivel 3. Esto reemplaza los valores actuales. Efectos y condiciones se conservan para revisión.')){state.hp=C.effectiveMax(state);state.temp=0;state.tempSource='none';state.agathysActive=false;state.hd=5;state.slots=2;state.reactionAvailable=true;save();refreshAfterMutation();toast('Recursos completos registrados por confirmación.');}},'save-concentration':async()=>{const next=$('#concentration').value;if(next!==state.concentration&&state.concentration!=='none'&&!await confirmChange('Cambiar concentración','Registrar otro efecto termina el anterior. No consume espacios porque se trata de un efecto ya lanzado.'))return;if(next==='hex'&&!$('#hex-target').value.trim())return toast('Escribe el objetivo de Maleficio.');state.concentration=next;state.hexTarget=next==='hex'?$('#hex-target').value.trim():'';if(next==='none')state.pendingConcentrationDC=null;clearConIfIncap();save();refreshAfterMutation();toast('Concentración registrada.');},'end-agathys':async()=>{if(await confirmChange('Finalizar Agathys','Confirma que la duración o el efecto terminó. Se eliminarán los PG temporales que todavía provengan de Agathys.')){state.agathysActive=false;if(state.tempSource==='agathys'){state.temp=0;state.tempSource='none';}save();refreshAfterMutation();}},'save-death':()=>{try{state.deathSuccess=validInt('#death-success',0,3);state.deathFail=validInt('#death-fail',0,3);save();refreshAfterMutation();toast('Salvaciones registradas.');}catch(err){toast(err.message);}},'death-20':async()=>{if(state.hp!==0||state.deathFail>=3)return toast('Esta opción requiere 0 PG y no haber muerto.');if(await confirmChange('20 natural en salvación de muerte','Confirma el 20 natural: recuperas 1 PG y se reinician éxitos y fallos.')){state.hp=1;state.deathSuccess=0;state.deathFail=0;save();refreshAfterMutation();}}};const fn=actions[e.target.closest('button')?.id];if(fn)await fn();});
document.addEventListener('submit',e=>{if(e.target.closest('#confirm-dialog'))return;e.preventDefault();try{
if(e.target.id==='sim-form')return;
if(e.target.id==='resources-form'){const max=validInt('#res-hpMax',1,1000),hp=validInt('#res-hp',0,max),temp=validInt('#res-temp',0,1000),slots=validInt('#res-slots',0,2),hd=validInt('#res-hd',0,5),source=$('#res-tempSource').value;if(source==='agathys'&&temp>15)throw new Error('Agathys de nivel 3 concede como máximo 15 PG temporales.');if(temp>0&&source==='none')throw new Error('Elige una fuente para los PG temporales.');state.hpMax=max;state.hp=Math.min(hp,C.effectiveMax(state));state.temp=temp;state.tempSource=temp?source:'none';state.agathysActive=temp>0&&source==='agathys';state.slots=slots;state.hd=hd;state.reactionAvailable=$('#res-reaction').checked;clearConIfIncap();if(state.hp>0){state.deathFail=0;state.deathSuccess=0;}save();refreshAfterMutation();toast('Estado de mesa registrado.');}
if(e.target.id==='add-item'){if(state.inventory.length>=500)throw new Error('Límite de 500 objetos. Exporta y reorganiza el inventario.');const name=$('#item-name').value.trim();if(!name)throw new Error('Escribe el nombre del objeto.');state.inventory.push({id:uid(),name,qty:validInt('#item-qty',0,99999),notes:$('#item-notes').value,kind:$('#item-kind').value,icon:$('#item-icon').value});save();refreshAfterMutation();toast('Objeto añadido.');}
if(e.target.id==='log-form'){const title=$('#log-title').value.trim(),body=$('#log-body').value.trim();if(!title||!body)throw new Error('La entrada requiere título y contenido.');if(state.logs.length>=3000)throw new Error('Límite de 3000 entradas. Exporta antes de reorganizar.');state.logs.push({id:uid(),date:$('#log-date').value,session:$('#log-session').value,type:$('#log-type').value,title,body,continuity:$('#log-continuity').value});save();renderBitacora();toast('Entrada guardada en la bitácora.');}
}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.bind){state[t.dataset.bind]=t.value;save();if(t.dataset.bind==='campaign')renderLore();}if(t.closest('#sim-form'))updateSim();if(t.id==='rules-search'){const q=t.value.toLocaleLowerCase('es');let n=0;$$('#reglas [data-search]').forEach(d=>{d.hidden=!d.dataset.search.includes(q);if(!d.hidden)n++;});$('#rules-empty').hidden=n>0;}if(t.id==='log-search')$('#log-history').innerHTML=renderLogs(t.value);if(t.dataset.itemField){const item=state.inventory.find(x=>x.id===t.closest('[data-item]').dataset.item);if(t.dataset.itemField==='qty'){if(!Number.isInteger(Number(t.value))||t.value===''||Number(t.value)<0||Number(t.value)>99999){t.setCustomValidity('Introduce una cantidad entera de 0 a 99999.');return;}t.setCustomValidity('');item.qty=Number(t.value);}else item[t.dataset.itemField]=t.value;save();renderFicha();updateSim();}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='import-file')importJSON(t.files[0]);if(t.dataset.condition){if(t.checked)state.conditions.push(t.dataset.condition);else state.conditions=state.conditions.filter(c=>c!==t.dataset.condition);clearConIfIncap();save();refreshAfterMutation();}if(t.id==='exhaustion'){state.exhaustion=Number(t.value);if(state.hp!==null)state.hp=Math.min(state.hp,C.effectiveMax(state));clearConIfIncap();save();refreshAfterMutation();}if(t.id==='round'){try{state.round=validInt('#round',1,999999);save();}catch(err){toast(err.message);}}});
$('.tabs').addEventListener('keydown',e=>{const tabs=$$('[role=tab]'),idx=tabs.indexOf(document.activeElement);if(idx<0)return;if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(idx+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setTab(tabs[n].dataset.tab,true);tabs[n].scrollIntoView({block:'nearest',inline:'center'});}});
window.addEventListener('hashchange',()=>setTab(location.hash.slice(1)));
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue!==JSON.stringify(state)){readProblem=true;showStorage('Otra ventana modificó esta hoja. Para evitar sobrescribirla, el guardado está detenido. Exporta tu estado actual y recarga para abrir la versión guardada.');$('#save-status').textContent='Conflicto entre ventanas · guardado detenido';}});
function applyPreset(name){const presets={duel:{distance:30,move:25,action:'luto',bonus:'hex',reaction:'none',target:state.hexTarget||''},blast:{distance:60,move:0,action:'blast',bonus:'hex',reaction:'none',target:state.hexTarget||''},escape:{distance:5,move:0,action:'blast',bonus:'misty',reaction:'none',teleport:30,teleportDirection:'away'},darkness:{distance:40,move:0,action:'darkness',bonus:'none',reaction:'reserve'},fire:{distance:80,move:0,action:'fireball',bonus:'none',reaction:'none'}};const p=presets[name];for(const[k,v]of Object.entries(p))$('#sim-'+k).value=v;$('#sim-direction').value='toward';$('#sim-reactionTrigger').checked=false;$('#sim-hostileNear').checked=false;updateSim();toast('Preset cargado. Revisa los supuestos y el objetivo antes de aplicar.');}
renderAll();setTab(location.hash.slice(1)||'ficha');$('#save-status').textContent=readProblem?'Guardado protegido · revisar Bitácora':storageOkay?'Local · guardado automático':'Sin guardado · exporta un respaldo';
})();
